 print("="*88);print(" OIAR-021 INSTALLER");print(" SNAPSHOT-NATIVE MARKET IDENTITY MATERIALIZER");print("="*88);print("[ROOT]",ROOT)
 for p in (ROOT/"qseries_v2/oracle_intelligence_analytics_runtime/oiar_004_indexed_current_cohort_analytics_materializer.py",ROOT/"qseries_v2/oracle_intelligence_analytics_runtime/oiar_003_canonical_market_history_access_index.py"):
  if not p.is_file():raise RuntimeError(f"Required proven upstream missing: {p}")
 ast.parse(SRC);ast.parse(TSRC);write(MOD,SRC);write(TEST,TSRC);subprocess.run([sys.executable,str(TEST)],cwd=str(ROOT),check=True)
 importlib.invalidate_caches();m=importlib.import_module("qseries_v2.oracle_intelligence_analytics_runtime.oiar_021_snapshot_native_market_identity_materializer");x=m.materialize_snapshot_native_identity(ROOT,10000)
 print(f"[PHYSICAL] snapshot_id={x['snapshot_id']} markets={x['market_count']} resolved={x['resolved_count']} unresolved={x['unresolved_count']} elapsed_seconds={x['elapsed_seconds']:.3f}")
